import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
// import { get_Org_details } from "@/mixins/GetOrgDetails.js";
import { formatedatetime } from "@/JsonFiles/DateFormate.js";
import { list_user_pettycash_transactions } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import RequestAdvanceDialog from "./RequestAdvanceDialog.vue";
import SnackBar from "@/components/SnackBar.vue";
import AddPettyCashDialog from './AddPettyCashDialog.vue';
import ViewExpenses from "./ExpensePopups/ViewExpenses.vue";
import { get_Org_details } from "@/mixins/GetOrgDetails.js";
import { getS3SignedUrl } from "@/mixins/S3GetStorageFile.js";
export default {
  name: "UserPettyCash",
  props: {
    currentBalance: {
      type: Number,
      default: 0
    }
  },
  components: {
    RequestAdvanceDialog,
    SnackBar,
    AddPettyCashDialog,
    ViewExpenses
  },
  mixins: [get_Org_details],
  data() {
    return {
      tableData: [],
      tableLoading: false,
      fixed: true,
      height: 0,
      windowHeight: 0,
      headers: [{
        title: "Entry Type",
        value: "entry_type",
        sortable: false,
        width: "120px"
      }, {
        title: "Expense Type",
        value: "expense_type",
        sortable: false,
        width: "120px"
      }, {
        title: "Transaction ID",
        value: "expense_transaction_id",
        sortable: false
      }, {
        title: "Category/Group",
        value: "expense_group_id_text",
        sortable: false
      }, {
        title: "Amount",
        value: "amount",
        sortable: false
      }, {
        title: "Granted Amount",
        value: "granted_amount",
        sortable: false
      }, {
        title: "Description",
        value: "expense_description",
        sortable: false
      }, {
        title: "Created On",
        value: "transaction_created_on",
        sortable: false
      }, {
        title: "Updated On",
        value: "updated_on",
        sortable: false
      }, {
        title: "Status",
        value: "transaction_status",
        sortable: false
      }, {
        title: "Documents",
        value: "docs",
        sortable: false
      }],
      search: "",
      currentPage: 1,
      totalItems: 0,
      itemsPerPage: 20,
      SnackBarComponent: {},
      advanceForm: {
        group: "",
        amount: "",
        comments: ""
      },
      // Document viewing
      rowInfo: {},
      expenseView: false,
      componentCheck: 0
    };
  },
  computed: {
    filteredItems() {
      if (!this.search) return this.tableData;
      const searchLower = this.search.toLowerCase();
      return this.tableData.filter(item => item.expense_group_id_text && item.expense_group_id_text.toLowerCase().includes(searchLower) || item.category_id_text && item.category_id_text.toLowerCase().includes(searchLower) || item.expense_description && item.expense_description.toLowerCase().includes(searchLower) || item.entry_type && item.entry_type.toLowerCase().includes(searchLower) || item.transaction_status && item.transaction_status.toLowerCase().includes(searchLower) || item.requested_amount && item.requested_amount.toString().includes(searchLower) || item.amount && item.amount.toString().includes(searchLower) || item.granted_amount && item.granted_amount.toString().includes(searchLower));
    },
    sortedAndPaginatedItems() {
      // First sort the filtered items
      const sortedItems = this.filteredItems.slice().sort((a, b) => {
        // Default sort by created date (newest first)
        const aValue = a.transaction_created_on ? a.transaction_created_on : 0;
        const bValue = b.transaction_created_on ? b.transaction_created_on : 0;
        return bValue - aValue;
      });

      // Then paginate
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return sortedItems.slice(start, end);
    },
    totalItems() {
      return this.filteredItems.length;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const pages = [];
      const startPage = Math.max(1, this.currentPage - 2);
      const endPage = Math.min(this.pageCount, this.currentPage + 2);
      if (startPage > 1) {
        pages.push(1);
        if (startPage > 2) {
          pages.push("...");
        }
      }
      for (let i = startPage; i <= endPage; i++) {
        pages.push(i);
      }
      if (endPage < this.pageCount) {
        if (endPage < this.pageCount - 1) {
          pages.push("...");
        }
        pages.push(this.pageCount);
      }
      return pages;
    },
    windowHeight() {
      return window.innerHeight - 280; // Adjust based on header/footer height
    }
    // currentBalance() {
    //   // Calculate the current balance from tableData or use a placeholder
    //   // Example: sum of all balances
    //   if (!this.tableData.length) return 0;
    //   return this.tableData.reduce((sum, item) => sum + (item.balance || 0), 0);
    // },
  },
  watch: {
    search() {
      this.currentPage = 1;
    },
    currentPage() {
      // When the page changes, scroll to top of table (optional)
      const table = document.querySelector(".modern-data-table");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  },
  mounted() {
    this.windowHeight = window.innerHeight - 280;
  },
  async created() {
    // await this.get_Org_details();
    await this.get_petty_cash_transactions();
  },
  methods: {
    async show_file(item) {
      try {
        if (!item.media_keys || item.media_keys === 'N/A') {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "warning",
            SnackbarText: "No document attached to this entry",
            timeout: 3000,
            Top: true
          };
          return;
        }

        // Check if it's an image file
        const fileExtension = item.media_keys.split(".").pop().toLowerCase();
        const isImage = ["jpg", "jpeg", "img", "png", "gif", "bmp", "webp"].includes(fileExtension);
        if (isImage) {
          // For images, open in dialog
          this.componentCheck = 2;
          this.rowInfo = item;
          this.expenseView = true;
        } else {
          // For PDFs and other documents, open in new window
          const details = this.$store.getters.GetOrgDetails;
          if (!details || !details.s3_details) {
            this.SnackBarComponent = {
              SnackbarVmodel: true,
              SnackbarColor: "red",
              SnackbarText: "S3 configuration not available",
              timeout: 3000,
              Top: true
            };
            return;
          }
          const signedUrl = await getS3SignedUrl(item.media_keys, details.s3_details);
          if (signedUrl) {
            window.open(signedUrl, '_blank');
          } else {
            this.SnackBarComponent = {
              SnackbarVmodel: true,
              SnackbarColor: "red",
              SnackbarText: "Failed to load document",
              timeout: 3000,
              Top: true
            };
          }
        }
      } catch (error) {
        console.error('Error opening file:', error);
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Error opening document",
          timeout: 3000,
          Top: true
        };
      }
    },
    get_date(date) {
      return formatedatetime(date);
    },
    async get_petty_cash_transactions() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_user_pettycash_transactions, {
          input: {}
        }));
        var response = JSON.parse(result.data.list_user_pettycash_transactions);
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          const balance = response.wallet_balence;
          this.tableLoading = false;
          this.tableData = response.data;
          this.totalItems = response.data.length;

          // Emit balance update to parent
          this.$emit('balance-updated', balance);
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    handleSortChange(value) {
      // Implement sorting logic here
    },
    successMsg(msg) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: msg,
        timeout: 5000,
        Top: true
      };
      this.tableData = [];
      this.totalItems = 0;
      this.get_petty_cash_transactions();

      // Emit balance update to parent
      this.$emit('balance-updated', this.currentBalance);
    },
    errorMsg(msg) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: msg,
        timeout: 5000,
        Top: true
      };
    }
  }
};
